function DebugBoxStartButton:__init(debugBox_, startButton_)


    self.debugBox = debugBox_    -- DebugBox
    self.startButton = startButton_ -- Button

    self.startBtnImage =  KTool.GetComponent(self.startButton.gameObject, typeof(Image))
    assert(self.startBtnImage)

    self.startButton.onClick:AddListener(function()
        self:OnPress()
    end)

    self.onOff = OnOff.Off
    self:Set(self.onOff)
end





function DebugBoxStartButton:__delete()
end



-- =========================================== Self ================================================ --

function DebugBoxStartButton:OnPress()

    self.onOff = (self.onOff == OnOff.On) and OnOff.Off or OnOff.On -- swap
    self:Set(self.onOff)
end



function DebugBoxStartButton:Set(state_)
    if state_ == OnOff.On then
        -- 功能开启:
        self.startBtnImage.color = Color(0, 0.5, 0.2, 1) -- 绿
        self.debugBox:OpenAll()
    else
        -- 功能关闭:
        self.startBtnImage.color = Color(0, 0.1, 0.4, 1) -- 蓝
        self.debugBox:CloseAll()
    end
end








return DebugBoxStartButton

